import { useEffect, useState } from "react";
import { BoardState } from "../types";

const STORAGE_KEY = "kanban-board";
const initialData: BoardState = {
  cards: {
    "1": { id: "1", title: "Task 1", description: "This is task 1" },
    "2": { id: "2", title: "Task 2", description: "This is task 2" },
    "3": { id: "3", title: "Task 3", description: "This is task 3" },
    "4": { id: "4", title: "Task 4", description: "This is task 4" },
    "5": { id: "5", title: "Task 5", description: "This is task 5" },
    "6": { id: "6", title: "Task 6", description: "This is task 6" },
    "7": { id: "7", title: "Task 7", description: "This is task 7" },
  },
  columns: {
    todo: {
      id: "todo",
      title: "Todo",
      cardIds: ["3","1", "2"],
    },
    inProgress: {
      id: "inProgress",
      title: "In Progress",
      cardIds: ["5"],
    },
    done: {
      id: "done",
      title: "Done",
      cardIds: [],
    },
  },
  columnOrder: ["todo", "inProgress", "done"],
};

export function useBoard() {
  const [board, setBoard] = useState<BoardState>(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      return stored ? JSON.parse(stored) : initialData;
    } catch {
      return initialData;
    }
  });

  useEffect(() => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(board));
}, [board])

  return {
    board,
    setBoard,
  };
}
